(function () {
  "use strict";
  var e = document.getElementById("themeToggleBtn");
  var t = document.getElementById("iconSun");
  var n = document.getElementById("iconMoon");
  function o(e) {
    document.documentElement.setAttribute("data-theme", e);
    localStorage.setItem("theme", e);
    if (t && n) {
      if (e === "dark") {
        t.style.display = "block";
        n.style.display = "none";
      } else {
        t.style.display = "none";
        n.style.display = "block";
      }
    }
  }
  (function () {
    var e = localStorage.getItem("theme");
    var t = e || (window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light");
    o(t);
  })();
  if (e) {
    e.addEventListener("click", function () {
      var e = document.documentElement.getAttribute("data-theme");
      o(e === "dark" ? "light" : "dark");
    });
  }
  var a = document.getElementById("langSwitcher");
  var r = document.getElementById("langBtn");
  var l = document.getElementById("langDropdown");
  var i = document.getElementById("langChevron");
  if (r && l) {
    r.addEventListener("click", function (e) {
      e.stopPropagation();
      var t = l.classList.contains("open");
      if (t) {
        l.classList.remove("open");
        if (i) i.classList.remove("open");
      } else {
        l.classList.add("open");
        if (i) i.classList.add("open");
      }
    });
    document.addEventListener("click", function () {
      l.classList.remove("open");
      if (i) i.classList.remove("open");
    });
    l.querySelectorAll(".langOption").forEach(function (t) {
      t.addEventListener("click", function () {
        var e = t.getAttribute("data-locale");
        if (e) {
          window.location.href = "/" + e;
        }
      });
    });
  }
  var c = [
    "Hello",
    "Olá",
    "Hola",
    "Bonjour",
    "Ciao",
    "Hej",
    "Hallo",
    "Salut",
    "Merhaba",
    "こんにちは",
    "Привет",
    "مرحبا",
  ];
  var s = document.getElementById("helloWord");
  if (s) {
    var d = 0;
    var u = c[0];
    var m = false;
    var f = null;
    function y() {
      var e = c[d];
      if (!m && u === e) {
        f = setTimeout(function () {
          m = true;
          y();
        }, 2e3);
        return;
      }
      if (m && u === "") {
        f = setTimeout(function () {
          m = false;
          d = (d + 1) % c.length;
          y();
        }, 200);
        return;
      }
      var t = m ? 30 : 60;
      f = setTimeout(function () {
        if (m) {
          u = u.slice(0, -1);
        } else {
          u = e.slice(0, u.length + 1);
        }
        s.textContent = u;
        y();
      }, t);
    }
    y();
  }
  var v = document.getElementById("techSearch");
  var p = document.getElementById("techGrid");
  if (v && p) {
    v.addEventListener("input", function () {
      var r = v.value.toLowerCase().trim();
      var e = p.querySelectorAll(".techCategory");
      e.forEach(function (e) {
        var t = (e.getAttribute("data-category-name") || "").toLowerCase();
        var n = e.querySelectorAll(".techSkillCard");
        var a = false;
        if (!r) {
          n.forEach(function (e) {
            e.style.display = "";
          });
          e.style.display = "";
          return;
        }
        if (t.includes(r)) {
          n.forEach(function (e) {
            e.style.display = "";
          });
          e.style.display = "";
          return;
        }
        n.forEach(function (e) {
          var t = (e.getAttribute("data-name") || "").toLowerCase();
          var n = (e.getAttribute("data-keywords") || "").toLowerCase();
          var o = t.includes(r) || n.includes(r);
          e.style.display = o ? "" : "none";
          if (o) a = true;
        });
        e.style.display = a ? "" : "none";
      });
    });
  }
  var g = document.getElementById("pdfViewerOverlay");
  var E = document.getElementById("pdfViewerFrame");
  var h = document.getElementById("viewResumeBtn");
  var w = "/static/documents/resume-ewerton.pdf";
  function L() {
    if (!g || !E) return;
    E.src = w;
    g.classList.add("open");
    document.body.style.overflow = "hidden";
  }
  function B(e) {
    if (e && e.target !== g) return;
    if (!g || !E) return;
    g.classList.remove("open");
    E.src = "";
    document.body.style.overflow = "";
  }
  window.closePdfViewer = B;
  if (h) {
    h.addEventListener("click", L);
  }
  var k = document.getElementById("companyModalOverlay");
  function I(e) {
    if (!k) return;
    k.querySelectorAll(".companyRoleSection").forEach(function (e) {
      e.style.display = "none";
    });
    var t = document.getElementById("modal-" + e);
    if (t) t.style.display = "block";
    k.classList.add("open");
    document.body.style.overflow = "hidden";
  }
  function b(e) {
    if (e && e.target !== k) return;
    if (!k) return;
    k.classList.remove("open");
    document.body.style.overflow = "";
  }
  window.openCompanyModal = I;
  window.closeCompanyModal = b;
  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") {
      if (g && g.classList.contains("open")) {
        g.classList.remove("open");
        if (E) E.src = "";
        document.body.style.overflow = "";
      }
      if (k && k.classList.contains("open")) {
        k.classList.remove("open");
        document.body.style.overflow = "";
      }
    }
  });
})();
